<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Interview;use App\Models\Job;use App\Models\JobApplication;use App\Models\JobFair;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class JobFairsCampaignsAndVideoTest extends TestCase{use RefreshDatabase;public function test_admin_publishes_fair_and_candidate_registers():void{$admin=User::factory()->create(['is_admin'=>true]);$response=$this->actingAs($admin,'sanctum')->postJson('/api/v1/admin/job-fairs',['title'=>'Feria Digital','description'=>'Conecta con empresas','format'=>'online','location_or_link'=>'https://example.com','starts_at'=>now()->addDay()->toISOString(),'ends_at'=>now()->addDays(2)->toISOString(),'status'=>'published'])->assertCreated();$candidate=User::factory()->create(['account_type'=>'candidate']);$this->actingAs($candidate,'sanctum')->postJson('/api/v1/candidate/job-fairs/'.$response->json('data.id').'/register')->assertOk();$this->assertDatabaseCount('job_fair_registrations',1);}public function test_mass_campaign_only_invites_visible_talent():void{[$owner,$company,$job]=$this->companyJob();$visible=User::factory()->create(['account_type'=>'candidate']);$visible->candidateProfile()->create(['professional_title'=>'Developer','province'=>'Santiago','talent_visibility'=>'companies','available_for_opportunities'=>true]);$hidden=User::factory()->create(['account_type'=>'candidate']);$hidden->candidateProfile()->create(['professional_title'=>'Developer','province'=>'Santiago','talent_visibility'=>'hidden','available_for_opportunities'=>true]);$campaign=$this->actingAs($owner,'sanctum')->postJson('/api/v1/company/recruitment-campaigns',['job_id'=>$job->id,'name'=>'Developers Santiago','filters'=>['province'=>'Santiago']])->assertCreated()->json('data');$this->actingAs($owner,'sanctum')->postJson('/api/v1/company/recruitment-campaigns/'.$campaign['id'].'/send')->assertOk()->assertJsonPath('data.invited_count',1);$this->assertDatabaseHas('talent_invitations',['candidate_user_id'=>$visible->id]);$this->assertDatabaseMissing('talent_invitations',['candidate_user_id'=>$hidden->id]);}public function test_video_interview_gets_secure_unique_room():void{[$owner,$company,$job]=$this->companyJob();$candidate=User::factory()->create(['account_type'=>'candidate']);$application=JobApplication::create(['job_id'=>$job->id,'user_id'=>$candidate->id,'status'=>'submitted','applied_at'=>now()]);$response=$this->actingAs($owner,'sanctum')->postJson('/api/v1/company/applications/'.$application->id.'/interviews',['title'=>'Entrevista','scheduled_at'=>now()->addDay()->toISOString(),'duration_minutes'=>30,'format'=>'video'])->assertCreated();$this->assertStringStartsWith('https://meet.jit.si/EmpleateRD-',$response->json('data.location_or_link'));}private function companyJob():array{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active','verification_status'=>'verified']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$job=Job::create(['company_id'=>$company->id,'created_by'=>$owner->id,'slug'=>'developer','title'=>'Developer','summary'=>'Puesto','description'=>'Trabajo','requirements'=>[],'benefits'=>[],'location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','currency'=>'DOP','status'=>'active']);return[$owner,$company,$job];}}
